import {preview,connection} from './config.js';
import {readState,execute} from './store.js';
import {allowed,profiles,capabilities,pageCapability,defaultAppearance,sectionLabels,inventorySection,quantity,valeryRecipe} from '../shared/workspace.js';
import {financeSummary} from '../shared/finance.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
let context,users=[],events=[],chatChannel='equipo',chatMessages={},chatAfter={},chatBusy=false,chatTimer,installPrompt;
let inventoryTab='all',stockFilter='all',chatDraft='',chatReference='';
export const access=()=>preview?{role:'admin',caps:Object.keys(capabilities)}:connection.access||{role:connection.role,caps:profiles[connection.role]?.caps||[]};
export const can=cap=>allowed(access(),cap);
export const canPage=page=>!pageCapability[page]||can(pageCapability[page]);
export const workspacePages=['appearance','sounds','users','chat','assistant','audit','valery','continuity','beverages'];
export const navGroups=[['Operación',[['areas','grid','Inicio'],['manual','plus','Nuevo pedido'],['orders','bag','Pedidos y cocina'],['cash','ticket','Taquilla'],['times','clock','Parque y gamer'],['tickets','receipt','Tickets y canjes']]],['Gestión',[['inventory','box','Inventario'],['beverages','bag','Bebidas'],['catalog','settings','Catálogo y recetas'],['customers','users','Clientes'],['finances','chart','Finanzas'],['chat','users','Chat del equipo']]],['Configuración',[['tables','qr','Mesas y QR'],['screens','screen','Televisores'],['users','users','Usuarios y permisos'],['appearance','sun','Apariencia'],['sounds','sound','Sonidos'],['continuity','link','Conexión e instalación'],['assistant','help','Ayuda del sistema'],['audit','chart','Actividad y respaldo']]]];
export function navigation(page,icon){return navGroups.map(([label,items])=>{const available=items.filter(([id])=>canPage(id));if(!available.length)return '';const buttons=available.map(([id,i,name])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}">${icon(i)}<span>${name}</span>${id==='orders'&&readState().orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length?'<i class="nav-activity"></i>':''}</button>`).join('');return label==='Configuración'?`<details class="nav-settings" ${available.some(([id])=>id===page)?'open':''}><summary>${icon('settings')} Configuración ${icon('down')}</summary><div>${buttons}</div></details>`:`<div class="nav-group-label">${label}</div>${buttons}`;}).join('');}
export function home(state,c){const pending=state.orders.filter(o=>o.status==='pending'),active=state.tickets.filter(t=>t.status==='active'),low=Object.entries(state.inventory||{}).filter(([,i])=>Number(i.stock)<=Number(i.minStock||0)),summary=financeSummary(state);const date=new Date().toLocaleDateString('es-VE',{timeZone:'America/Caracas',weekday:'long',day:'numeric',month:'long'});return `${c.head('Hoy en Divermanía',date,`${can('orders.create')?'<button class="btn primary" data-page="manual">＋ Nuevo pedido</button>':''}${can('passes.sell')?'<button class="btn" data-action="new-ticket">Vender pase</button>':''}`)}${c.notice()}<div class="workspace-stats">${[['Pedidos por atender',pending.length,'orders','bag'],['Sesiones activas',active.length,'times','clock'],['Artículos por reponer',low.length,'inventory','box'],['Balance registrado',c.money(summary.balance),'finances','chart']].filter(([, ,p])=>canPage(p)).map(([name,value,p,ico])=>`<button class="workspace-stat" data-page="${p}"><span class="stat-icon">${c.icon(ico)}</span><span>${name}</span><strong>${value}</strong><small>Abrir ${p==='times'?'sesiones':p==='inventory'?'inventario':p==='finances'?'finanzas':'pedidos'} →</small></button>`).join('')}</div><div class="workspace-home-grid"><section class="panel"><div class="panel-head"><div><h2>En marcha</h2><p>Lo que necesita atención ahora.</p></div>${c.badge('En vivo')}</div><div class="panel-body">${can('orders.view')?pending.slice(0,4).map(o=>`<button class="work-row" data-action="order-detail" data-id="${esc(o.id)}"><span class="work-number">#${o.number}</span><span><strong>${esc(o.name||'Visitante')}</strong><small>${o.items.length} productos · pendiente de confirmación</small></span>${c.icon('right')}</button>`).join(''):''}${can('passes.view')?active.filter(t=>t.endAt<=Date.now()+300000).slice(0,4).map(t=>`<button class="work-row" data-action="session-detail" data-id="${esc(t.id)}"><span class="work-number">${c.icon('clock')}</span><span><strong>${esc(t.name||'Pase #'+t.number)}</strong><small>${t.endAt<=Date.now()?'Tiempo terminado':'Termina pronto'} · ${t.area==='play'?'Gamer':'Parque'}</small></span>${c.icon('right')}</button>`).join(''):''}${!pending.length&&!active.some(t=>t.endAt<=Date.now()+300000)?'<div class="workspace-empty"><span>✓</span><h3>Todo al día</h3><p>Los pedidos nuevos y los tiempos próximos aparecerán aquí.</p></div>':''}</div></section><section class="panel"><div class="panel-head"><h2>Tu jornada, a un clic</h2></div><div class="panel-body work-shortcuts">${[['orders','bag','Cocina','Confirmar, preparar y entregar'],['times','game','Parque y gamer','Activar pases y controlar tiempos'],['inventory','box','Reponer existencias','Ingredientes, snacks y bebidas'],['assistant','help','Necesito ayuda','Guías rápidas del sistema']].filter(([p])=>canPage(p)).map(([p,i,title,sub])=>`<button class="work-row" data-page="${p}"><span class="stat-icon">${c.icon(i)}</span><span><strong>${title}</strong><small>${sub}</small></span>${c.icon('right')}</button>`).join('')}</div></section></div>${can('orders.view')?receptionCard(state):''}<section class="panel gap-top"><div class="panel-head"><h2>El local también vive en estas pantallas</h2></div><div class="workspace-links"><a href="/cliente" target="_blank" rel="noopener">${c.icon('bag')} Menú del cliente ↗</a>${can('screens')?'<button data-page="screens">Configurar televisores →</button>':''}<button data-page="continuity">Instalar la aplicación →</button>${access().role==='admin'?'<button data-action="work-delivery">Preparar entrega →</button>':''}</div></section>`;}
export function receptionCard(state){const r=state.workspace?.reception||{},online=Date.now()-(r.lastSeen||0)<90000;return `<div class="reception-card ${r.paused?'paused':''}"><div><strong>${r.paused?'Pedidos web pausados':online?'Este local está recibiendo pedidos':'Conecta un equipo para recibir pedidos'}</strong><p>Mantén Inicio, Cocina o Taquilla abierto. Si falla el wifi, usa los datos de un teléfono.</p></div>${can('orders.update')?`<button class="btn" data-action="work-reception" data-paused="${r.paused?'0':'1'}">${r.paused?'Reanudar pedidos':'Pausar pedidos web'}</button>`:''}</div>`;}
export function inventory(state,c,search=''){const all=Object.entries(state.inventory||{}),list=all.filter(([,i])=>(inventoryTab==='all'||inventorySection(i)===inventoryTab)&&(stockFilter==='all'||stockFilter==='low'&&Number(i.stock)>0&&Number(i.stock)<=Number(i.minStock||0)||stockFilter==='out'&&Number(i.stock)<=0)&&String(i.name).toLowerCase().includes(search.toLowerCase()));return `${c.head('Inventario','Cada presentación tiene sus propias existencias.',`${can('inventory.edit')?'<button class="btn" data-action="ingredient-new">＋ Ingrediente o consumible</button>':''}<button class="btn" data-action="work-shopping">Reposición sugerida</button>${can('costs')?'<button class="btn" data-action="work-costs">Costos de compra</button>':''}${can('catalog')?'<button class="btn primary" data-action="catalog-new-unit">＋ Snack o bebida</button>':''}`)}${c.notice()}<div class="inventory-overview"><span><strong>${all.length}</strong> artículos</span><span><strong>${all.filter(([,i])=>i.stock<=i.minStock).length}</strong> por reponer</span><span><strong>${all.filter(([,i])=>i.stock<=0).length}</strong> agotados</span></div><div class="tabs inventory-tabs">${[['all','Todo'],...Object.entries(sectionLabels)].map(([key,label])=>`<button class="tab ${inventoryTab===key?'active':''}" data-action="work-inventory-tab" data-key="${key}">${label} <small>${all.filter(([,i])=>key==='all'||inventorySection(i)===key).length}</small></button>`).join('')}</div><div class="section-tools"><div class="search">${c.icon('search')}<input id="inventory-search" value="${esc(search)}" placeholder="Buscar artículo o presentación" aria-label="Buscar inventario"></div><select id="work-stock-filter" aria-label="Estado del inventario">${[['all','Todas las existencias'],['low','Stock bajo'],['out','Agotados']].map(([v,n])=>`<option value="${v}" ${stockFilter===v?'selected':''}>${n}</option>`).join('')}</select></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Artículo</th><th>Existencias</th><th>Mínimo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${list.map(([id,i])=>`<tr><td><strong>${esc(i.name)}</strong><small>${sectionLabels[inventorySection(i)]}${i.valeryCode?' · Valery '+esc(i.valeryCode):''}</small></td><td class="stock-quantity">${quantity(i.stock)} <small>${esc(i.unit)}</small></td><td>${quantity(i.minStock)} ${esc(i.unit)}</td><td>${c.badge(i.stock<=0?'Agotado':i.stock<=i.minStock?'Stock bajo':'Disponible',i.stock<=0?'red':i.stock<=i.minStock?'orange':'')}</td><td><div class="actions">${can('purchases')?`<button class="btn small" data-action="inventory-purchase" data-id="${esc(id)}">Entrada / compra</button>`:''}${can('inventory.move')?`<button class="btn small" data-action="work-stock-adjust" data-id="${esc(id)}">Merma / conteo</button>`:''}${can('inventory.edit')?`<button class="btn small" data-action="ingredient-edit" data-id="${esc(id)}">Editar</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="workspace-empty"><h3>No hay artículos en esta vista</h3><p>Cambia los filtros o añade un artículo.</p></div>':''}</section><details class="help-details"><summary>Cómo se descuenta el inventario</summary><p>Un snack o bebida empacado se descuenta por unidad y presentación. La comida y las cotufas preparadas usan una receta con cantidades verificadas. Los canjes de pases consumen las mismas existencias que las ventas.</p></details>`;}
function beveragesPage(state,c){const drinks=state.catalog.filter(p=>p.cat==='bebidas');return `${c.head('Bebidas','Cada tamaño y presentación tiene su propio precio e inventario.','<button class="btn primary" data-action="new-beverage">＋ Añadir bebida</button>')}<section class="panel"><div class="panel-body">${drinks.length?drinks.map(p=>`<div class="work-row"><span><strong>${esc(p.name)}</strong><small>${c.money(p.price)} · ${quantity(state.inventory[p.stockItemId]?.stock)} unidades</small></span><button class="btn small" data-action="catalog-edit" data-id="${esc(p.id)}">Editar bebida</button></div>`).join(''):'<div class="workspace-empty"><h3>Añade las bebidas del local</h3><p>Registra refrescos, aguas y jugos con su presentación y precio real. Después carga las existencias desde Inventario.</p></div>'}</div></section>`;}
const field=(name,label,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const fonts=[['system','Sistema · clara'],['rounded','Redondeada'],['serif','Clásica'],['condensed','Compacta']];
function appearancePage(state,c){const a={...defaultAppearance,...state.workspace?.appearance};return `${c.head('Dale tu estilo','Tus preferencias se aplican únicamente a tu panel y a tu cuenta.')}<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Mi apariencia</h2></div><form id="work-appearance-form" class="panel-body"><div class="color-fields">${field('primary','Color principal',a.primary,'color')}${field('sidebar','Menú lateral',a.sidebar,'color')}${field('surface','Tarjetas',a.surface,'color')}${field('background','Fondo',a.background,'color')}${field('ink','Texto',a.ink,'color')}</div><div class="form-grid">${['font','heading'].map(key=>`<label class="field"><span>${key==='font'?'Tipografía de lectura':'Tipografía de títulos'}</span><select name="${key}">${fonts.map(([v,n])=>`<option value="${v}" ${a[key]===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><label class="field"><span>Tamaño del texto</span><select name="textScale">${[[1,'Normal'],[1.1,'Grande'],[1.2,'Muy grande']].map(([v,n])=>`<option value="${v}" ${a.textScale===v?'selected':''}>${n}</option>`).join('')}</select></label><p class="form-note">Solo cambia tu panel. El menú del cliente y los televisores conservan su diseño. La vista previa cambia mientras eliges.</p><div class="actions"><button class="btn primary" type="submit">Guardar apariencia</button><button class="btn" type="button" data-action="work-theme-reset">Restaurar original</button></div><p class="form-error" role="alert"></p></form></section><section class="panel appearance-preview"><span class="eyebrow">DIVERMANÍA</span><h2>Comida y diversión.</h2><p>Un estilo propio y fácil de leer en cada pantalla.</p><span class="preview-illustration">✦</span><button class="btn primary" type="button">Así se verán tus botones</button><small>Los colores de alerta mantienen su significado.</small></section></div>`;}
function soundSettings(){try{return {volume:.5,tone:'chime',newOrder:true,ready:true,times:true,...JSON.parse(localStorage.getItem('divermania.sounds')||'{}')};}catch{return {volume:.5,tone:'chime',newOrder:true,ready:true,times:true};}}
export function soundNotes(mode){const p=soundSettings();if(mode==='end'&&!p.times||mode==='ready'&&!p.ready||mode==='newOrder'&&!p.newOrder)return null;const melodies={chime:[660,880,1100],arcade:[523,784,1046,1318],soft:[440,554,659],bell:[880,1174,1568]};return {notes:mode==='end'?[880,660,880,660]:melodies[mode==='newOrder'?(p.newOrderTone||p.tone):mode==='ready'?(p.readyTone||'arcade'):p.tone]||melodies.chime,volume:Number(p.volume)||.001,wave:p.tone==='arcade'?'square':'sine'};}
function soundPage(c){const p=soundSettings();return `${c.head('Sonidos y avisos','Estas preferencias se guardan solo en este dispositivo.')}<section class="panel settings-panel"><form id="work-sounds-form" class="panel-body"><label class="field"><span>Melodía</span><select name="tone">${[['chime','Campanilla'],['arcade','Arcade'],['soft','Suave'],['bell','Timbre']].map(([v,n])=>`<option value="${v}" ${p.tone===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field"><span>Volumen</span><input type="range" name="volume" min="0" max="1" step=".05" value="${p.volume}"></label><div class="form-grid">${[['newOrderTone','Sonido de nuevo pedido'],['readyTone','Sonido de pedido listo']].map(([key,label])=>`<label class="field"><span>${label}</span><select name="${key}">${[['chime','Campanilla'],['arcade','Arcade'],['soft','Suave'],['bell','Timbre']].map(([v,n])=>`<option value="${v}" ${(p[key]||(key==='readyTone'?'arcade':p.tone))===v?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div>${[['newOrder','Nuevo pedido'],['ready','Pedido listo'],['times','Avisos previos: 5 minutos y 1 minuto']].map(([v,n])=>`<label class="check-line"><input type="checkbox" name="${v}" ${p[v]?'checked':''}><span>${n}</span></label>`).join('')}<div class="actions"><button class="btn primary" type="submit">Guardar preferencias</button><button class="btn" type="button" data-action="work-sound-test">Escuchar prueba</button><button class="btn" type="button" data-action="sound">Activar sonido del navegador</button></div><p class="form-note">Al terminar una sesión, la sirena es continua hasta validar el aviso y mantiene un volumen mínimo de alerta. Reconocerlo no libera la estación. El navegador requiere un primer clic para habilitar el audio.</p></form></section>`;}
function usersPage(c){return `${c.head('Usuarios y permisos','El propietario decide qué puede hacer cada persona.', '<button class="btn" data-action="work-users-load">Actualizar equipo</button><button class="btn primary" data-action="work-user-new">＋ Añadir persona</button>')}<section class="panel"><div class="panel-head"><h2>Accesos del equipo</h2></div><div class="panel-body"><p>Selecciona una cuenta existente y adapta su perfil. El cambio exige que esa persona vuelva a iniciar sesión.</p><div id="work-users-list">${users.length?users.map(u=>`<div class="work-row"><span class="avatar">${esc((u.email||'E')[0].toUpperCase())}</span><div><strong>${esc(u.email||u.id)}</strong><small>${u.owner?'Propietario':u.disabled?'Acceso suspendido':profiles[u.profile]?.name||'Sin perfil personalizado'}</small></div>${u.owner?'':`<button class="btn small" data-action="work-user-edit" data-id="${esc(u.id)}">Editar permisos</button>`}</div>`).join(''):'<div class="workspace-empty"><h3>Consulta las cuentas del equipo</h3><p>Pulsa Actualizar equipo para cargar los usuarios autorizados.</p></div>'}</div><p class="form-note">Añade a cada persona con su propio correo y perfil; después puedes ajustar sus capacidades. El acceso del propietario se conserva.</p></div></section>`;}
function chatPage(c){const old=$('#work-chat-form');if(old){chatDraft=old.message.value;chatReference=old.reference.value;}return `${c.head('Chat del equipo','Mensajes internos; solo los ve el personal autorizado.')}<section class="panel chat-shell"><nav class="tabs">${[['equipo','Equipo'],['cocina','Cocina'],['parque','Parque y gamer']].map(([id,n])=>`<button class="tab ${chatChannel===id?'active':''}" data-action="work-chat-channel" data-key="${id}">${n}</button>`).join('')}</nav><div id="work-chat-messages" class="chat-messages" aria-live="polite">${chatHTML()}</div><form id="work-chat-form" class="chat-compose"><label class="sr-only" for="work-message">Mensaje</label><textarea id="work-message" name="message" maxlength="1200" required placeholder="Escribe al equipo…">${esc(chatDraft)}</textarea><label class="sr-only" for="work-chat-reference">Pedido o pase relacionado</label><input id="work-chat-reference" name="reference" maxlength="120" placeholder="Pedido # o pase · opcional" value="${esc(chatReference)}"><button class="btn primary" type="submit">Enviar</button></form><p class="form-note chat-footnote">Historial reciente de hasta 40 mensajes. Se consulta mientras esta pantalla está abierta.</p></section>`;}
function chatHTML(){const list=chatMessages[chatChannel]||[];return list.length?list.map(m=>`<article class="chat-message ${m.actor===connection.user?.uid?'own':''}"><div><strong>${esc(m.name)}</strong><time>${new Date(m.at).toLocaleTimeString('es-VE',{timeZone:'America/Caracas',hour:'2-digit',minute:'2-digit'})}</time></div><p>${esc(m.text)}</p>${m.reference?`<small>${esc(m.reference)}</small>`:''}</article>`).join(''):'<div class="workspace-empty"><h3>La conversación empieza aquí</h3><p>Coordina pedidos, cocina y tiempos con el equipo.</p></div>';}
const guides=[
 ['Tomar un pedido','manual','Selecciona los productos, la variante y las observaciones. Revisa el resumen y guarda una sola vez. El número aparece después de que el servidor confirma.'],
 ['Confirmar y preparar pedidos','orders','Un pedido nuevo queda pendiente de confirmación del local. Comenzar preparación confirma que cocina lo recibió. Marca Listo al terminar y Entregado cuando se retire.'],
 ['Vender y activar un pase','cash','Vende el pase con el pago confirmado. En Parque y gamer elige el pase, activa el tiempo y asigna una estación si corresponde. Al vencer, confirma la salida para liberar el espacio.'],
 ['Snacks, bebidas y presentaciones','inventory','Cada botella, bolsa y tamaño tiene un artículo y existencias propias. Un Doritos pequeño y uno grande son productos distintos. Las cotufas preparadas descuentan los insumos de su receta.'],
 ['Registrar una compra o una merma','inventory','Entrada / compra suma stock y registra el gasto una sola vez. Merma / conteo permite registrar pérdida, autoconsumo o conteo físico con motivo.'],
 ['No hay internet','continuity','Activa los datos de un teléfono y comparte su conexión con los equipos. Conserva el carrito o borrador: no está enviado hasta recibir confirmación. El local deja de aceptar pedidos web si no hay un equipo receptor conectado.'],
 ['Imprimir un ticket','tickets','La impresión es opcional. Abre el ticket y elige Imprimir. Selecciona en el sistema operativo la impresora térmica de 58 o 80 mm. Reimprimir conserva el número y no genera otra venta.'],
 ['Finanzas y tasa BCV','finances','El balance suma cobros confirmados y movimientos, y resta gastos. La tasa histórica del movimiento conserva la conversión elegida. Un abono registra el cobro o pago y reduce el saldo. No representa utilidad neta contable ni emite factura fiscal.'],
 ['Editar permisos','users','El propietario selecciona una cuenta, parte de un perfil y ajusta sus capacidades. Los permisos se comprueban en el servidor. La persona debe volver a iniciar sesión tras el cambio.']
];
function assistantPage(c){return `${c.head('Te ayudamos a usar Divermanía','Busca una tarea y abre su guía.')}<section class="panel assistant-panel"><div class="panel-body"><span class="assistant-symbol">✦</span><h2>¿Qué necesitas hacer?</h2><label class="search"><span class="sr-only">Buscar ayuda</span><input id="work-help-search" placeholder="Ej. vender un pase, imprimir, inventario…"></label><div id="work-help-results">${guideHTML('')}</div><p class="form-note">Asistente de guías del sistema. Las respuestas provienen de procedimientos definidos. Una IA conversacional requiere conectar un proveedor y sus límites de uso.</p></div></section>`;}
function guideHTML(query){const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''),tokens=normalize(query).split(/[^a-z0-9]+/).filter(w=>w.length>2&&!['como','puedo','quiero','para','con','una','que','las','los','del','por','hacer','tengo','donde','necesito','sistema'].includes(w));const rows=guides.map(row=>({row,score:tokens.reduce((n,w)=>n+(normalize(row[0]+' '+row[2]).includes(w)?1:0),0)})).filter(x=>!tokens.length||x.score>0).sort((a,b)=>b.score-a.score);return rows.map(({row:[title,page,body]},i)=>`<details class="help-details" ${query&&i===0?'open':''}><summary>${title}</summary><p>${body}</p>${canPage(page)?`<button class="btn small" data-page="${page}">Abrir sección →</button>`:''}</details>`).join('')||'<p>No encontré esa tarea. Prueba con “pedido”, “pase”, “stock” o “caja”.</p>';}
function continuityPage(c){return `${c.head('Tu aplicación, siempre a mano','Funciona en el navegador y se puede instalar.')}<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Instalar Divermanía</h2></div><div class="panel-body"><p>En Chrome o Edge, usa Instalar aplicación en el menú del navegador. En iPhone o iPad: Compartir → Añadir a pantalla de inicio.</p><button class="btn primary" data-action="work-install">Instalar aplicación</button><p id="work-install-note" class="form-note">La instalación depende del navegador y del dispositivo.</p><label class="field gap-top"><span>Ancho de la impresora de este equipo</span><select id="work-printer-width"><option value="80" ${localStorage.getItem('divermania.printer')!=='58'?'selected':''}>80 mm</option><option value="58" ${localStorage.getItem('divermania.printer')==='58'?'selected':''}>58 mm</option></select></label><p class="form-note">Los tickets digitales siguen disponibles. Imprimir abre el diálogo del equipo; requiere una impresora instalada.</p></div></section><section class="panel"><div class="panel-head"><h2>Si se cae el internet del local</h2></div><div class="panel-body"><ol class="help-steps"><li>Activa los datos de un teléfono y comparte internet.</li><li>Conecta la computadora o tablet que recibe los pedidos.</li><li>Abre Cocina o Inicio y comprueba el estado de conexión.</li><li>Recupera el resultado de un envío pendiente antes de repetirlo.</li></ol><div class="banner-info">Sin conexión puedes consultar el menú guardado y conservar borradores. Los pedidos, pagos y cambios de stock requieren confirmación del servidor. Los tiempos ya iniciados continúan según su hora de finalización.</div><p class="form-note">La información guardada puede estar desactualizada. La aplicación indica cuando se está consultando una copia.</p></div></section></div>`;}
function valeryPage(state,c){const staged=state.workspace?.valery||valeryRecipe;return `${c.head('Datos de Valery','Receta transcrita de tus capturas; conserva las cantidades sin inventar unidades.')}<section class="panel"><div class="panel-head"><div><h2>332 · Hamburguesa Trampolín Pollo</h2><p>Variante independiente de la de carne.</p></div>${c.badge(staged.status==='reviewed'?'Revisada':'Pendiente de revisión','orange')}</div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>Código</th><th>Componente</th><th>Cantidad capturada</th><th>Unidad</th></tr></thead><tbody>${valeryRecipe.components.map(r=>`<tr><td>${r.code}</td><td>${esc(r.name)}</td><td>${r.qty}</td><td>${r.unit||'<span class="badge orange">Por confirmar</span>'}</td></tr>`).join('')}</tbody></table></div><p class="form-note">Las existencias de esas capturas son históricas. El jamón mostraba 9.060 g (9,06 kg); no se usa como conteo actual. Los costos y precios quedan pendientes de verificación.</p><div class="actions"><button class="btn" data-action="work-valery-stage">Guardar referencia</button><button class="btn primary" data-action="work-valery-review">Vincular y revisar receta</button></div></div></section>`;}
function auditPage(c){return `${c.head('Actividad y respaldo','Consulta cambios y descarga una copia para revisión.', '<button class="btn" data-action="work-audit-load">Actualizar actividad</button><button class="btn primary" data-action="work-export">Descargar respaldo</button><button class="btn" data-action="work-backup-review">Revisar una copia</button>')}<section class="panel"><div class="panel-body">${events.length?events.map(e=>`<div class="work-row"><span><strong>${esc(e.type)}</strong><small>${new Date(e.at).toLocaleString('es-VE',{timeZone:'America/Caracas'})} · ${esc(e.actor)}</small>${e.reason?`<small>${esc(e.reason)}</small>`:''}</span></div>`).join(''):'<div class="workspace-empty"><h3>Historial de cambios recientes</h3><p>Actualiza para consultar los últimos movimientos de esta versión.</p></div>'}<p class="form-note">El respaldo incluye datos del local. Guárdalo en un lugar privado. Restaurar requiere validar la copia y conciliar los cambios antes de reemplazar registros.</p></div></section>`;}
export function workspacePage(page,state,c){context=c;return ({beverages:()=>beveragesPage(state,c),appearance:()=>appearancePage(state,c),sounds:()=>soundPage(c),users:()=>usersPage(c),chat:()=>chatPage(c),assistant:()=>assistantPage(c),continuity:()=>continuityPage(c),valery:()=>valeryPage(state,c),audit:()=>auditPage(c)})[page]?.();}
const fontCSS={system:'Inter,system-ui,sans-serif',rounded:'"Trebuchet MS",system-ui,sans-serif',serif:'Georgia,serif',condensed:'"Arial Narrow",Impact,sans-serif'};
export function applyAppearance(value,persist=true){if(document.documentElement.dataset.appView!=='staff'&&!/\/(admin|inventario|imagenes|ticketeras|televisores|gestion)(\.html)?$/.test(location.pathname))return;const a={...defaultAppearance,...value},root=document.documentElement;root.style.setProperty('--brand',a.primary);root.style.setProperty('--orange',a.primary);for(const key of ['--primary','--brand-red'])root.style.setProperty(key,a.primary);root.style.setProperty('--bg',a.background);root.style.setProperty('--ink',a.ink);root.style.setProperty('--work-bg',a.background);root.style.setProperty('--work-sidebar',a.sidebar);root.style.setProperty('--work-surface',a.surface);const light=hex=>{const h=hex.slice(1),c=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*c[0]+.7152*c[1]+.0722*c[2]>.179;};root.style.setProperty('--work-sidebar-ink',light(a.sidebar)?'#29231e':'#fff5ea');root.style.setProperty('--work-button-ink',light(a.primary)?'#29231e':'#ffffff');document.querySelector('meta[name=theme-color]')?.setAttribute('content',a.primary);root.style.setProperty('--work-ink',a.ink);root.style.setProperty('--work-font',fontCSS[a.font]||fontCSS.system);root.style.setProperty('--work-heading',fontCSS[a.heading]||fontCSS.system);root.style.setProperty('--work-scale',a.textScale);if(persist)try{localStorage.setItem('divermania.appearance.user.'+(preview?'demo':connection.user?.uid||'guest'),JSON.stringify(a));}catch{}}
function formTask(form,task,c){form.onsubmit=e=>{e.preventDefault();c.submit(form,task);};}
async function pollChat(){if(chatBusy||!$('#work-chat-messages')||document.hidden)return;chatBusy=true;try{const channel=chatChannel,r=await execute('chat.list',{channel,after:chatAfter[channel]||0});const map=new Map((chatMessages[channel]||[]).map(m=>[m.id,m]));r.messages.forEach(m=>map.set(m.id,m));chatMessages[channel]=[...map.values()].sort((a,b)=>a.at-b.at).slice(-40);chatAfter[channel]=Math.max(chatAfter[channel]||0,...r.messages.map(m=>m.at));if(chatChannel===channel&&$('#work-chat-messages')){const box=$('#work-chat-messages'),near=box.scrollHeight-box.scrollTop-box.clientHeight<80;box.innerHTML=chatHTML();if(near||!chatAfter[channel])box.scrollTop=box.scrollHeight;}}catch(e){if($('#work-chat-messages')&&!chatMessages[chatChannel]?.length)$('#work-chat-messages').innerHTML=`<p class="form-note">${esc(e.message)}</p>`;}finally{chatBusy=false;}}
export function pruneActions(root=document){const required={'new-order':'orders.create','new-ticket':'passes.sell','new-station':'screens','control-settings':'screens','start-picker':'sessions','start-session':'sessions','edit-visitor':'passes.edit','finish-session':'sessions','extend':'passes.sell','confirm-payment':'payments','assign-customer':'customers','new-customer':'customers','cancel-order':'orders.cancel','order-next':'orders.update','catalog-new':'catalog','catalog-new-unit':'catalog','catalog-edit':'catalog','catalog-delete':'catalog','menu-image-edit':'catalog','import-menu':'catalog','ingredient-new':'inventory.edit','ingredient-edit':'inventory.edit','inventory-purchase':'purchases','inventory-out':'inventory.move','print':'print','print-order':'print','tables-print':'print'};for(const b of root.querySelectorAll('[data-action]'))if(required[b.dataset.action]&&!can(required[b.dataset.action]))b.remove();for(const b of root.querySelectorAll('[data-page]'))if(!canPage(b.dataset.page))b.remove();}
export function mountWorkspace(page,c){context=c;clearInterval(chatTimer);if(page==='chat'){pollChat();chatTimer=setInterval(pollChat,12000);const f=$('#work-chat-form');formTask(f,async()=>{await execute('chat.send',{channel:chatChannel,text:f.message.value,reference:f.reference.value},f.dataset.key||=(crypto.randomUUID()));f.message.value='';f.reference.value='';chatDraft='';chatReference='';const current=$('#work-chat-form');if(current){current.message.value='';current.reference.value='';}delete f.dataset.key;await pollChat();},c);}if(page==='appearance'){const f=$('#work-appearance-form'),read=()=>Object.fromEntries(new FormData(f));f.oninput=()=>{f.dataset.dirty='true';applyAppearance(read(),false);};formTask(f,async()=>{await execute('appearance.save',read());delete f.dataset.dirty;await c.refreshWorkspace?.();c.toast('Apariencia guardada.');},c);}if(page==='sounds'){const f=$('#work-sounds-form');formTask(f,async()=>{saveSounds(f);c.toast('Sonidos guardados para este equipo.');},c);}if($('#work-stock-filter'))$('#work-stock-filter').onchange=e=>{stockFilter=e.target.value;c.render();};if($('#work-help-search'))$('#work-help-search').oninput=e=>{$('#work-help-results').innerHTML=guideHTML(e.target.value);};if($('#work-printer-width'))$('#work-printer-width').onchange=e=>localStorage.setItem('divermania.printer',e.target.value);}
function saveSounds(f){localStorage.setItem('divermania.sounds',JSON.stringify({tone:f.tone.value,newOrderTone:f.newOrderTone.value,readyTone:f.readyTone.value,volume:Number(f.volume.value),newOrder:f.newOrder.checked,ready:f.ready.checked,times:f.times.checked}));}
export async function workspaceAction(action,b,c){if(!action?.startsWith('work-'))return false;context=c;const state=readState();switch(action){
 case 'work-delivery':deliveryForm(state,c);break;
 case 'work-inventory-tab':inventoryTab=b.dataset.key;c.render();break;
 case 'work-reception':await execute('orders.availability',{paused:b.dataset.paused==='1'});await c.refreshWorkspace?.();c.toast(b.dataset.paused==='1'?'Pedidos web pausados.':'Pedidos web reanudados.');break;
 case 'work-theme-reset':if($('#work-appearance-form'))delete $('#work-appearance-form').dataset.dirty;await execute('appearance.save',defaultAppearance);applyAppearance(defaultAppearance);await c.refreshWorkspace?.();c.render();break;
 case 'work-sound-test':if($('#work-sounds-form'))saveSounds($('#work-sounds-form'));await c.previewSound?.();break;
 case 'work-install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else c.toast('Usa el menú del navegador: Instalar aplicación o Añadir a pantalla de inicio.');break;
 case 'work-users-load':{const r=await execute('access.list');users=r.users;c.render();break;}
 case 'work-user-new':newUser(c);break;
 case 'work-user-edit':editUser(users.find(u=>u.id===b.dataset.id),c);break;
 case 'work-chat-channel':chatChannel=b.dataset.key;c.render();break;
 case 'work-shopping':{const rows=Object.values(state.inventory).filter(i=>Number(i.stock)<=Number(i.minStock||0));c.modal('Lista de reposición',`<p class="form-note">Sugerencia para alcanzar el doble del mínimo configurado. Ajusta la compra según el consumo real; no se registra ningún gasto automáticamente.</p>${rows.length?'<div class="table-scroll"><table><thead><tr><th>Artículo</th><th>Existencia</th><th>Sugerencia de compra</th></tr></thead><tbody>'+rows.map(i=>{const n=Math.max(0,2*Number(i.minStock||0)-Number(i.stock));return `<tr><td>${esc(i.name)}</td><td>${quantity(i.stock)} ${esc(i.unit)}</td><td>${i.minStock>0?quantity(i.unit==='und'?Math.ceil(n):Math.ceil(n*1000)/1000)+' '+esc(i.unit):'Configura su mínimo'}</td></tr>`;}).join('')+'</tbody></table></div>':'<div class="workspace-empty"><h3>Las existencias están por encima de sus mínimos</h3></div>'}`,true);break;}
 case 'work-costs':{const r=await execute('workspace.costs');c.modal('Últimos costos de compra',`<p class="form-note">Costos por unidad de las compras registradas en esta versión. No son costos históricos verificados de recetas ni utilidad contable.</p>${r.costs.length?'<div class="table-scroll"><table><thead><tr><th>Artículo</th><th>Último costo por unidad</th><th>Fecha</th></tr></thead><tbody>'+r.costs.map(i=>`<tr><td>${esc(i.name)}</td><td>$${Number(i.unitCostUsd).toLocaleString('es-VE',{maximumFractionDigits:5})} / ${esc(i.unit)}</td><td>${new Date(i.verifiedAt).toLocaleDateString('es-VE',{timeZone:'America/Caracas'})}</td></tr>`).join('')+'</tbody></table></div>':'<div class="workspace-empty"><h3>Aún no hay costos de compra registrados</h3><p>Registra una entrada / compra con su cantidad y costo real.</p></div>'}`,true);break;}
 case 'work-stock-adjust':adjustStock(b.dataset.id,state,c);break;
 case 'work-valery-stage':await execute('valery.stage');await c.refreshWorkspace?.();c.toast('Referencia guardada. Las existencias actuales se conservan.');break;
 case 'work-valery-review':reviewValery(state,c);break;
 case 'work-backup-review':reviewBackup(c);break;
 case 'work-audit-load':events=(await execute('workspace.audit')).events;c.render();break;
 case 'work-export':{const backup=await execute('workspace.export'),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='divermania-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);c.toast('Respaldo descargado.');break;}
 case 'work-abono':abono(b.dataset.kind,b.dataset.id,state,c);break;
 case 'work-shift':shiftForm(state,c);break;
 case 'work-refund':refundForm(b.dataset.id,c);break;
 case 'work-notifications':notifications(state,c);break;
 }return true;}
function newUser(c){c.modal('Añadir persona al equipo',`<form id="work-user-new-form">${field('displayName','Nombre','','text','required maxlength="80"')}${field('email','Correo electrónico','','email','required autocomplete="off"')}${field('password','Contraseña inicial · mínimo 10 caracteres','','password','required minlength="10" maxlength="128" autocomplete="new-password"')}<label class="field"><span>Perfil de partida</span><select name="profile">${Object.entries(profiles).filter(([id])=>id!=='admin').map(([id,p])=>`<option value="${id}" ${id==='cash'?'selected':''}>${p.name}</option>`).join('')}</select></label><p class="form-note">Comparte la contraseña directamente con esa persona. Puedes editar sus permisos después de crearla.</p><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Volver</button><button type="submit" class="btn primary">Crear cuenta del equipo</button></div></form>`);const f=$('#work-user-new-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute('access.create',{email:f.email.value,password:f.password.value,name:f.displayName.value,profile:f.profile.value,caps:profiles[f.profile.value].caps},key);c.closeModal();users=(await execute('access.list')).users;c.render();c.toast('Cuenta creada con su perfil.');},c);}
function reviewBackup(c){c.modal('Revisar una copia de respaldo',`<form id="work-backup-form"><label class="field"><span>Archivo de respaldo de Divermanía</span><input name="backup" type="file" accept="application/json,.json" required></label><p class="form-note">La revisión se hace en este dispositivo. Compara los datos antes de planear una restauración.</p><button class="btn primary" type="submit">Revisar contenido</button></form><div id="work-backup-result"></div>`,true);const f=$('#work-backup-form');formTask(f,async()=>{const file=f.backup.files[0];if(!file||file.size>16*1024*1024)throw new Error('Selecciona una copia JSON de hasta 16 MB.');let value;try{value=JSON.parse(await file.text());}catch{throw new Error('El archivo no contiene JSON válido.');}if(!['divermania-backup-v1','divermania-demo-backup-v1'].includes(value.format)||!value.data||typeof value.data!=='object')throw new Error('Esta copia no tiene el formato de respaldo de Divermanía.');const rows=Object.entries(value.data).filter(([,v])=>Array.isArray(v));for(const [name,list] of rows){if(list.some(r=>!r||typeof r!=='object'))throw new Error('Registros inválidos en '+name+'.');const ids=list.map(r=>r.id).filter(Boolean);if(new Set(ids).size!==ids.length)throw new Error('Hay identificadores duplicados en '+name+'.');}$('#work-backup-result').innerHTML=`<div class="banner-info gap-top"><strong>Copia reconocida</strong><p>Fecha: ${esc(value.createdAt||'Sin fecha')}. ${value.format.includes('demo')?'Contiene datos de demostración.':'Contiene datos operativos.'}</p></div><div class="table-scroll"><table><thead><tr><th>Sección</th><th>Registros</th></tr></thead><tbody>${rows.map(([name,list])=>`<tr><td>${esc(name)}</td><td>${list.length}</td></tr>`).join('')}</tbody></table></div><p class="form-note">La revisión no reemplaza los datos actuales. Para restaurar, se deben conciliar ventas, existencias y cambios posteriores a esta fecha.</p>`;},c);}
function deliveryForm(state,c){c.modal('Preparar entrega · pedidos de prueba',`<form id="delivery-form"><p class="form-note">Selecciona únicamente pedidos ficticios. Se guardan archivados para auditoría y salen de la operación y del balance. El menú, los precios, los pases y las compras se conservan. Cierra el turno de pruebas antes de abrir el primer turno real.</p>${state.orders.map(o=>`<label class="check-line"><input type="checkbox" name="order" value="${esc(o.id)}"><span>#${o.number} · ${esc(o.name)} · ${c.money(o.total)}</span></label>`).join('')||'<p>No hay pedidos activos para archivar.</p>'}<label class="check-line gap-top"><input type="checkbox" name="restock"><span>Devolver los insumos descontados: confirmo que estos productos de prueba no se consumieron realmente.</span></label>${field('confirm','Escribe PRUEBAS para confirmar','','text','required pattern="PRUEBAS"')}<p class="form-note">Descarga un respaldo desde Actividad y respaldo antes de preparar la entrega. Los correlativos se conservan para evitar repetir números.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Archivar los seleccionados</button></div></form>`,true);const f=$('#delivery-form'),keys=new Map();formTask(f,async()=>{const ids=[...f.querySelectorAll('[name=order]:checked')].map(e=>e.value);if(!ids.length)throw new Error('Selecciona los pedidos ficticios.');for(const id of ids){if(!keys.has(id))keys.set(id,crypto.randomUUID());await execute('delivery.archive',{id,confirm:f.confirm.value,restock:f.restock.checked},keys.get(id));}c.closeModal();c.toast('Pedidos de prueba archivados. Revisa las existencias antes de entregar.');},c);}
function editUser(user,c){if(!user)return;const profile=user.profile||'cash',caps=user.caps||profiles[profile].caps;c.modal('Permisos de '+esc(user.email),`<form id="work-access-form"><label class="field"><span>Perfil de partida</span><select name="profile">${Object.entries(profiles).filter(([id])=>id!=='admin').map(([id,p])=>`<option value="${id}" ${id===profile?'selected':''}>${p.name}</option>`).join('')}</select></label>${field('displayName','Nombre para el equipo',user.name||user.email?.split('@')[0]||'Equipo')}<div class="capability-grid">${Object.entries(capabilities).map(([id,name])=>`<label class="check-line"><input type="checkbox" name="capability" value="${id}" ${caps.includes(id)?'checked':''}><span>${name}</span></label>`).join('')}</div><label class="check-line"><input type="checkbox" name="disabled" ${user.disabled?'checked':''}><span>Suspender este acceso</span></label><p class="form-note">El empleado debe cerrar sesión y volver a entrar después del cambio.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Guardar permisos</button></div></form>`,true);const f=$('#work-access-form');f.profile.onchange=()=>{const checked=profiles[f.profile.value].caps;f.querySelectorAll('[name=capability]').forEach(el=>el.checked=checked.includes(el.value));};const key=crypto.randomUUID();formTask(f,async()=>{await execute('access.save',{id:user.id,profile:f.profile.value,name:f.displayName.value,caps:[...f.querySelectorAll('[name=capability]:checked')].map(el=>el.value),disabled:f.disabled.checked},key);c.closeModal();users=(await execute('access.list')).users;c.render();c.toast('Permisos guardados. Solicita que vuelva a iniciar sesión.');},c);}
function adjustStock(id,state,c){const item=state.inventory[id];if(!item)return;c.modal('Movimiento de '+esc(item.name),`<form id="work-stock-form"><p>Existencia actual: <strong>${quantity(item.stock)} ${esc(item.unit)}</strong></p><label class="field"><span>Tipo de ajuste</span><select name="kind"><option value="waste">Merma / pérdida</option><option value="self">Autoconsumo</option><option value="count">Conteo físico · sustituye la existencia</option></select></label>${field('qty','Cantidad ('+item.unit+')','','number',`required min="0" step="${item.unit==='und'?'1':'.001'}"`)}<label class="field"><span>Motivo</span><textarea name="reason" required maxlength="400" placeholder="Explica el movimiento para el historial"></textarea></label><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Registrar ajuste</button></div></form>`);const f=$('#work-stock-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute('inventory.adjust',{id,kind:f.kind.value,qty:Number(f.qty.value),reason:f.reason.value},key);c.closeModal();c.toast('Movimiento registrado.');},c);}
function reviewValery(state,c){c.modal('Verificar receta de Valery',`<form id="work-valery-form"><label class="field"><span>Producto Trampolín del catálogo</span><select name="productId" required><option value="">Seleccionar</option>${state.catalog.filter(p=>/trampol/i.test(p.name)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>${field('option','Variante exacta · si tiene opciones','Pollo')}<p class="form-note">Vincula cada código con un insumo existente. Confirma la cantidad y unidad reales de la receta; no uses existencias históricas.</p>${valeryRecipe.components.map((r,i)=>`<div class="valery-component"><strong>${r.code} · ${esc(r.name)}</strong><div class="form-grid"><label class="field"><span>Insumo</span><select name="item${i}" required><option value="">Vincular insumo</option>${Object.entries(state.inventory).map(([id,item])=>`<option value="${esc(id)}">${esc(item.name)} (${esc(item.unit)})</option>`).join('')}</select></label>${field('qty'+i,'Cantidad',r.qty,'number','min=".001" step=".001" required')}<label class="field"><span>Unidad verificada</span><select name="unit${i}" required><option value="">Confirmar</option>${['g','ml','und'].map(u=>`<option value="${u}" ${r.unit===u?'selected':''}>${u}</option>`).join('')}</select></label></div></div>`).join('')}<label class="check-line"><input type="checkbox" name="verified" required><span>Verifiqué las cantidades y unidades de esta receta de pollo.</span></label><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Guardar para después</button><button type="submit" class="btn primary">Aplicar receta verificada</button></div></form>`,true);const f=$('#work-valery-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute('valery.apply',{productId:f.productId.value,option:f.option.value,components:valeryRecipe.components.map((r,i)=>({id:f.elements['item'+i].value,qty:Number(f.elements['qty'+i].value),unit:f.elements['unit'+i].value}))},key);c.closeModal();c.toast('Receta de pollo aplicada.');},c);}
export function paymentInputs(state,reference=true){return `<div class="form-grid"><label class="field"><span>Moneda del pago</span><select name="currency"><option value="USD">Dólares</option><option value="VES">Bolívares</option></select></label><label class="field"><span>Forma de pago</span><select name="method"><option value="efectivo">Efectivo</option><option value="pago_movil">Pago móvil</option><option value="tarjeta">Tarjeta</option><option value="transferencia">Transferencia</option><option value="otro">Otro</option></select></label></div>${field('rate','Tasa utilizada · Bs por USD',state.exchangeRate?.value||'','number','min=".0001" step=".0001"')}${reference?field('externalRef','Referencia / comprobante de Valery · opcional',''):''}`;}
export const paymentPayload=f=>({currency:f.currency?.value||'USD',method:f.elements.method?.value||'efectivo',rate:Number(f.rate?.value||0),externalRef:f.externalRef?.value||''});
function abono(kind,id,state,c){const rows=state.finances?.[kind==='cxc'?'receivables':'payables']||Object.entries(state.legacy?.[kind]||{}).map(([id,d])=>({id,...d})),d=rows.find(d=>d.id===id);if(!d)return;const balance=(d.amountCents??Math.round(d.monto*100))-(d.paidCents||0);c.modal('Registrar abono',`<form id="work-abono-form"><p>Saldo pendiente: <strong>${c.money(balance)}</strong></p>${field('amount','Abono ($)','','number',`min=".01" step=".01" max="${balance/100}" required`)}${paymentInputs(state)}<p class="form-note">Registra el movimiento de caja y reduce el saldo una sola vez.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Registrar abono</button></div></form>`);const f=$('#work-abono-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute('finance.payment',{kind,id,amount:Number(f.amount.value),...paymentPayload(f)},key);c.closeModal();c.toast('Abono registrado.');},c);}
export function shiftCard(state,c){const s=state.workspace?.shift;return `<div class="reception-card"><div><strong>${s?.status==='open'?'Turno de caja abierto':'Caja sin turno abierto'}</strong><p>${s?.status==='open'?'Fondo inicial: '+c.money(s.openingCents)+' · '+new Date(s.openedAt).toLocaleString('es-VE',{timeZone:'America/Caracas'}):'Registra fondo inicial, cobros y conteo por moneda.'}</p></div><button class="btn" data-action="work-shift">${s?.status==='open'?'Cerrar turno':'Abrir turno'}</button></div>${s?.status==='closed'&&typeof s.differenceCents==='number'?`<div class="banner-info"><strong>Último cierre</strong><p>Efectivo esperado USD: ${c.money(s.expectedCents)} · Diferencia: ${c.money(s.differenceCents)}<br>Efectivo esperado Bs: ${quantity(s.expectedVESCents/100)} · Diferencia Bs: ${quantity(s.differenceVESCents/100)}</p><small>Los pagos electrónicos se registran aparte del efectivo.</small></div>`:''}`;}
function shiftForm(state,c){const open=state.workspace?.shift?.status==='open';c.modal(open?'Cerrar turno de caja':'Abrir turno de caja',`<form id="work-shift-form">${field('amount',open?'Efectivo contado · USD':'Fondo inicial · USD','','number','min="0" step=".01" required')}${field('amountVES',open?'Efectivo contado · Bs':'Fondo inicial · Bs',0,'number','min="0" step=".01" required')}<label class="field"><span>Observaciones</span><textarea name="notes" maxlength="400"></textarea></label><p class="form-note">Se conserva apertura, movimientos y conteo. Los pagos electrónicos se separan del efectivo. Los turnos abiertos antes de esta actualización requieren conciliación manual. El cierre no equivale a utilidad contable.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">${open?'Confirmar cierre':'Abrir caja'}</button></div></form>`);const f=$('#work-shift-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute(open?'finance.shift.close':'finance.shift.open',{amount:Number(f.amount.value),amountVES:Number(f.amountVES.value),notes:f.notes.value},key);await c.refreshWorkspace?.();c.closeModal();c.render();c.toast(open?'Turno cerrado.':'Turno abierto.');},c);}
function refundForm(id,c){c.modal('Registrar devolución de dinero',`<form id="work-refund-form">${field('amount','Monto devuelto ($)','','number','min=".01" step=".01" required')}<label class="field"><span>Motivo</span><textarea name="reason" required maxlength="400"></textarea></label>${paymentInputs(readState())}<p class="form-note">Registra el dinero devuelto por fuera. No ejecuta una transferencia bancaria ni cancela el pedido.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Registrar devolución</button></div></form>`);const f=$('#work-refund-form'),key=crypto.randomUUID();formTask(f,async()=>{await execute('finance.refund',{id,amount:Number(f.amount.value),reason:f.reason.value,...paymentPayload(f)},key);c.closeModal();c.toast('Devolución registrada.');},c);}
function notifications(state,c){const expired=state.tickets.filter(t=>t.status==='active'&&t.endAt<=Date.now()),pending=state.orders.filter(o=>o.status==='pending'),low=Object.entries(state.inventory).filter(([,i])=>i.stock<=i.minStock);c.modal('Centro de avisos',`${can('passes.view')?expired.map(t=>`<div class="work-row"><span><strong>Tiempo terminado · ${esc(t.name||'#'+t.number)}</strong><small>${t.area==='play'?'Gamer':'Parque'}</small></span><button class="btn small" data-action="session-detail" data-id="${esc(t.id)}">Ver sesión</button></div>`).join(''):''}${can('orders.view')&&pending.length?`<div class="work-row"><span><strong>${pending.length} pedidos sin confirmar</strong><small>La cocina debe comenzar su preparación.</small></span><button class="btn small" data-page="orders" data-action="close-modal">Ver pedidos</button></div>`:''}${can('inventory.view')&&low.length?`<div class="work-row"><span><strong>${low.length} artículos por reponer</strong><small>Revisa las existencias mínimas.</small></span><button class="btn small" data-page="inventory" data-action="close-modal">Ver inventario</button></div>`:''}${!expired.length&&!pending.length&&!low.length?'<div class="workspace-empty"><h3>Todo al día</h3><p>No tienes avisos pendientes.</p></div>':''}`);}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
export function restoreAppearance(){try{applyAppearance(JSON.parse(localStorage.getItem('divermania.appearance.user.'+(preview?'demo':connection.user?.uid||'guest'))||'{}'));}catch{}}
window.addEventListener('divermania-session-ready',restoreAppearance);
restoreAppearance();
